    cpu.a = u(ini, "a") as u8;
    cpu.f = u(ini, "f") as u8;
    cpu.b = u(ini, "b") as u8;
    cpu.c = u(ini, "c") as u8;
    cpu.d = u(ini, "d") as u8;
    cpu.e = u(ini, "e") as u8;
    cpu.h = u(ini, "h") as u8;
    cpu.l = u(ini, "l") as u8;
    cpu.sp = u(ini, "sp") as u16;
    cpu.pc = u(ini, "pc") as u16;
