        (0xE1, 0x1E, C, 0x00, Z | H | C),
        (0x0F, 0x00, C, 0x10, H), // 只靠进位输入产生半进位
        (0xFF, 0x00, C, 0x00, Z | H | C), // 只靠进位输入产生全进位
        (0x0F, 0x00, 0, 0x0F, 0), // C=0 时与 ADD 相同
