//! `Snapshot for Cpu` 往返测试（core 通道）：保存并恢复全部字段，包括 EI 挂起、HALT bug、锁死等内部状态。

#[path = "cpu_common.rs"]
mod common;

use common::{FlatBus, IE, IF};
use gb_core::state::{Snapshot, StateError, StateReader, StateWriter};
use gb_core::Cpu;

fn save(cpu: &Cpu) -> Vec<u8> {
    let mut w = StateWriter::new();
    cpu.save(&mut w);
    w.into_inner()
}

fn odd_cpu() -> Cpu {
    let mut cpu = Cpu::new();
    cpu.a = 0x12;
    cpu.f = 0xA0;
