/// 子模块（IF/IE、定时器、串口、Joypad、PPU、DMA、卡带）由 `Machine::save_state` 逐个写出。
impl Snapshot for Bus {
    fn save(&self, w: &mut StateWriter) {
        w.tag(b"BUS ");
        w.bytes(&self.wram[..]);
        w.bytes(&self.hram);
        w.bytes(&self.apu);
        w.u64(self.mcycles);
    }

    fn load(&mut self, r: &mut StateReader) -> Result<(), StateError> {
        r.tag(b"BUS ")?;
