    /// 开机状态：FF46 读 0xFF（Power_Up_Sequence 的 DMG 列），没有进行中的传输。
    pub fn new() -> Self {
        Self { reg: 0xFF, page: 0, index: DMA_LEN, pending: None, transferring: false }
    }

