1	//! SM83 CPU（core 通道，T10/T11/T14）。
2	//!
3	//! 冻结部分（D001）：`CpuBus` trait、`Cpu` 的公开字段、`Cpu::new`、`Cpu::step`、`Snapshot for Cpu`。
4	//! 新增的公开字段 `ei_pending`/`halt_bug`/`locked` 与 `af/bc/de/hl` 访问器不改变冻结签名。
5	//!
6	//! 时序模型（PLAN §3.3）：每条指令按真实的 M-cycle 序列调用 `read/write/idle`，每次调用 = 1 M-cycle。
7	//! `step` 的取指是第 1 个 M-cycle（PC 指向操作码本身），与 SingleStepTests 的约定一致。
8	//! 内部周期位置：
9	//! - `PUSH rr`、`RST`：取指后 1 个 idle，再写高字节、低字节；
10	//! - `CALL nn` / `CALL cc`（成立）：读完 nn 后 1 个 idle，再压栈；
11	//! - `RET`/`RETI`：弹栈后 1 个 idle；`RET cc`：判断条件 1 个 idle，成立时弹栈后再 1 个 idle；
12	//! - `JP nn`、`JP cc`（成立）、`JR e`、`JR cc`（成立）：最后 1 个 idle；`JP HL` 没有内部周期；
13	//! - `ADD HL,rr`、`INC/DEC rr`、`LD SP,HL`：1 个 idle；`ADD SP,e`：2 个 idle；`LD HL,SP+e`：1 个 idle。
14	//!
15	//! 访问时点（mem_timing）：`INC/DEC (HL)` 读在第 2、写在第 3 个 M-cycle；CB 前缀 `BIT b,(HL)` 读在第 3 个；
16	//! 其余 CB `(HL)` 读在第 3、写在第 4 个；`LD (nn),A` 写在第 4 个；`LD A,(nn)` 读在第 4 个。
17	//!
18	//! 中断（PLAN §3.3、Pan Docs Interrupts.md / halt.md）：每条指令结束后（即下一次 `step` 开始时）检查
19	//! `IME && pending()`；分派共 5 M-cycle：2 个 idle、写 PCH、写 PCL、1 个 idle，PC=向量。
20	//! 向量在写完 PCH 之后才决定：若压栈写到了 IE（SP 指向 0xFFFF）并使中断不再挂起，则 PC=0x0000、IF 不清除。
21	//! `EI` 延迟一条指令生效（紧跟 `DI` 则不生效），`DI` 立即生效，`RETI` 立即置 IME。
22	
23	use crate::alu::{self, Flags};
24	use crate::decode::{self, AluOp, CbInstr, Instr, RotOp, Rp, Rp2, RpMem, R8};
25	use crate::state::{Snapshot, StateError, StateReader, StateWriter};
26	
27	/// CPU 看到的总线。每次调用恰好消耗 1 个 M-cycle（`pending`/`ack` 除外，它们不耗时）。
28	pub trait CpuBus {
29	    /// 读一个字节：1 M-cycle。
30	    fn read(&mut self, addr: u16) -> u8;
31	    /// 写一个字节：1 M-cycle。
32	    fn write(&mut self, addr: u16, v: u8);
33	    /// 内部周期：1 M-cycle，无总线访问。
34	    fn idle(&mut self);
35	    /// `IE & IF & 0x1F`，不耗时。
36	    fn pending(&self) -> u8;
37	    /// 清除 IF 的第 `bit` 位（`bit` 为序号 0..=4，0 = VBlank），不耗时。
38	    fn ack(&mut self, bit: u8);
39	    /// 执行 STOP 时调用（不耗时）：Bus 借此清零 DIV。测试用的假总线可以不实现。
40	    fn stop(&mut self) {}
41	}
42	
43	/// DI 的操作码：紧跟在 EI 之后时取消 EI 的延迟生效。
44	const OP_DI: u8 = 0xF3;
45	
46	/// 寄存器与 CPU 状态。`Cpu::new` 给出 DMG 开机（boot ROM 结束、PC=0x0100）时的值；
47	/// F 的 H/C 取决于头部校验和，由 `Machine::new` 修正。
48	#[derive(Debug, Clone, PartialEq, Eq)]
49	pub struct Cpu {
50	    pub a: u8,
51	    /// 低 4 位恒为 0。
52	    pub f: u8,
53	    pub b: u8,
54	    pub c: u8,
55	    pub d: u8,
56	    pub e: u8,
57	    pub h: u8,
58	    pub l: u8,
59	    pub sp: u16,
60	    pub pc: u16,
61	    pub ime: bool,
62	    pub halted: bool,
63	    /// 执行 0x40（LD B,B）时置位；`Machine::ld_b_b_hit` 读取后清零。
64	    pub ld_b_b: bool,
65	    /// 刚执行过 EI：IME 将在下一条指令执行完之后置 1（若那条指令是 DI 则取消）。
66	    pub ei_pending: bool,
67	    /// HALT bug 已触发：下一次取操作码时 PC 不前进（该字节被读两次）。
68	    pub halt_bug: bool,
69	    /// 执行了非法操作码，CPU 锁死：此后每次 `step` 只做 1 次 `idle`。
70	    pub locked: bool,
71	}
72	
73	impl Default for Cpu {
74	    fn default() -> Self {
75	        Self::new()
76	    }
77	}
78	
79	impl Cpu {
80	    /// DMG 开机状态（Pan Docs Power_Up_Sequence，DMG 列）：A=01 F=B0 B=00 C=13 D=00 E=D8 H=01 L=4D SP=FFFE PC=0100。
81	    pub fn new() -> Self {
82	        Self {
83	            a: 0x01,
84	            f: 0xB0,
85	            b: 0x00,
86	            c: 0x13,
87	            d: 0x00,
88	            e: 0xD8,
89	            h: 0x01,
90	            l: 0x4D,
91	            sp: 0xFFFE,
92	            pc: 0x0100,
93	            ime: false,
94	            halted: false,
95	            ld_b_b: false,
96	            ei_pending: false,
97	            halt_bug: false,
98	            locked: false,
99	        }
100	    }
101	
102	    /// 执行 1 条指令，或 1 次中断分派，或 HALT/锁死状态下的 1 个 M-cycle。
103	    /// 每次调用至少消耗 1 个 M-cycle（至少调用一次 read/write/idle），绝不为 0。
104	    pub fn step<B: CpuBus>(&mut self, bus: &mut B) {
105	        if self.locked {
106	            bus.idle();
107	            return;
108	        }
109	        if self.halted {
110	            if bus.pending() == 0 {
111	                // 外设由 bus 在这个 M-cycle 里照常推进。
112	                bus.idle();
113	                return;
114	            }
115	            // 有挂起中断即唤醒，不额外耗时：与用一串 NOP 等待中断的时序相同（Pan Docs halt.md）。
116	            self.halted = false;
117	        }
118	        if self.ime && bus.pending() != 0 {
119	            self.dispatch(bus);
