"""Frame-exact replay helper: expands logged actions into a per-frame button schedule."""
import json
from gbemu.backend import GbEmuEmulator

BOOT = 60

def schedule(log, upto=None):
    """Return list of (button or None) per frame after boot, plus per-request start frames."""
    reqs = [json.loads(l) for l in open(log)]
    if upto is not None:
        reqs = reqs[:upto]
    frames, starts = [], []
    for r in reqs:
        starts.append(BOOT + len(frames))
        for a in r.get("actions") or []:
            p = a.strip().lower().split("_")
            if p[0] in ("press", "walk"):
                frames += ["_".join(p[1:])] * 8 + [None] * 12
            elif p[0] == "hold":
                frames += ["_".join(p[1:-1])] * int(p[-1])
            elif p[0] == "wait":
                frames += [None] * int(p[1])
            else:
                raise ValueError(a)
    return frames, starts

class Runner:
    def __init__(self, rom, log, upto=None, lib_emu=None):
        self.sched, self.starts = schedule(log, upto)
        self.emu = GbEmuEmulator(); self.emu.load(rom); self.emu.tick(BOOT)
    def run_to(self, frame):
        e = self.emu
        while e.frame_count < frame:
            b = self.sched[e.frame_count - BOOT] if e.frame_count - BOOT < len(self.sched) else None
            if b: e.press(b, 1)
            else: e.tick(1)
    def tilemap(self):
        tm = self.emu.read_range(0xC3A0, 360)
        return [tm[r*20:(r+1)*20] for r in range(18)]
EOF
