//! Throwaway tracer for the Oak's Lab stall (not part of the repo).
use gb_core::Machine;
use std::collections::HashMap;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let rom = std::fs::read(&args[1]).unwrap();
    let sched: Vec<u8> = std::fs::read_to_string(&args[2]).unwrap().lines().map(|l| l.parse().unwrap()).collect();
    let f0: u64 = args[3].parse().unwrap();
    let f1: u64 = args[4].parse().unwrap();
    let mut m = Machine::new(rom).unwrap();
    let names: HashMap<u16, &str> = [
        (0x4c34, "_UpdateSprites"), (0x4b0f, "PrepareOAMData"), (0x2024, "VBlank"), (0x20af, "DelayFrame"),
        (0x4ed1, "UpdateNPCSprite"), (0x4e31, "UpdatePlayerSprite"), (0x2429, "UpdateSprites"), (0x03ff, "OverworldLoop"),
        (0x0402, "OverworldLoopLessDelay"), (0x101b, "RunMapScript"),
    ].into_iter().collect();
    let watch: [(u16, &str); 6] = [(0xC162, "spr6.img"), (0xC172, "spr7.img"), (0xC1A2, "spr10.img"), (0xC1B2, "spr11.img"), (0xFF90, "hOAMoff"), (0xC45C, "tile(8,9)")];
    let mut budget: i64 = 0;
    let mut frame: u64 = 0;
    let mut t_in_frame: i64;
    loop {
        let mask = if frame >= 60 { *sched.get((frame - 60) as usize).unwrap_or(&0) } else { 0 };
        m.set_buttons(mask);
        budget += 70224;
        t_in_frame = 0;
        let tracing = frame >= f0 && frame < f1;
        let mut last: Vec<u8> = watch.iter().map(|w| m.peek(w.0)).collect();
        if tracing {
            println!("==== frame {frame} start: buttons={mask:02x} LY={} pc={:04x}", m.peek(0xFF44), m.regs().pc);
        }
        while budget > 0 {
            let r0 = m.regs();
            let bank = m.peek(0xFFB8);
            let ly0 = m.peek(0xFF44);
            let t = m.step() as i64;
            budget -= t;
            t_in_frame += t;
            if !tracing {
                continue;
            }
            let r1 = m.regs();
            if let Some(n) = names.get(&r0.pc) {
                if r0.pc < 0x4000 || bank == 1 {
                    let extra = if r0.pc == 0x4ed1 { format!(" hCurrentSpriteOffset={:02x}", m.peek(0xFF8E)) } else { String::new() };
                    println!("  t={t_in_frame:6} LY={ly0:3} enter {n}{extra}");
                }
            }
            if matches!(r1.pc, 0x40 | 0x48 | 0x50 | 0x58 | 0x60) && r1.sp == r0.sp.wrapping_sub(2) && !r1.ime && r0.ime {
                let ret = m.peek(r1.sp) as u16 | (m.peek(r1.sp.wrapping_add(1)) as u16) << 8;
                println!("  t={t_in_frame:6} LY={ly0:3} IRQ -> {:02x} (interrupted pc={ret:04x} bank={bank}) halted_before={}", r1.pc, r0.halted);
            }
            for (i, w) in watch.iter().enumerate() {
                let v = m.peek(w.0);
                if v != last[i] {
                    println!("  t={t_in_frame:6} LY={:3} {} {:02x} -> {:02x} (pc {:04x} bank {})", m.peek(0xFF44), w.1, last[i], v, r0.pc, bank);
                    last[i] = v;
                }
            }
        }
        frame += 1;
        if frame >= f1 {
            break;
        }
    }
}
EOF
